  3	import com.pousadamareal.db.Database;
  4	import com.pousadamareal.handler.*;
  5	import io.javalin.Javalin;
  6	import org.slf4j.Logger;
  7	import org.slf4j.LoggerFactory;
  8	
  9	public class Main {
 10	    private static final Logger logger = LoggerFactory.getLogger(Main.class);
 11	
 12	    public static void main(String[] args) {
 13	        String port = System.getenv("PORT");
 14	        int serverPort = port != null ? Integer.parseInt(port) : 7070;
 15	
 16	        logger.info("Iniciando Pousada Maré Alta");
 17	
 18	        Database.initialize();
 19	
 20	        Javalin app = Javalin.create()
 21	            .get("/rooms", RoomHandler::listRooms)
 22	            .post("/reservations", ReservationHandler::create)
 23	            .get("/reservations/:id", ReservationHandler::get)
 24	            .post("/reservations/:id/confirmation", ReservationHandler::confirm)
 25	            .post("/reservations/:id/cancellation", ReservationHandler::cancel)
 26	            .post("/reservations/:id/check-in", ReservationHandler::checkIn)
 27	            .post("/reservations/:id/check-out", ReservationHandler::checkOut)
 28	            .get("/reservations/:id/document", ReservationHandler::getDocument)
 29	            .get("/messages", MessageHandler::listMessages)
 30	            .get("/reports/occupancy", ReportHandler::occupancy)
 31	            .get("/reports/revenue", ReportHandler::revenue)
 32	            .exception(Exception.class, (e, ctx) -> {
 33	                logger.error("Erro não esperado", e);
 34	                ctx.status(500).json(jsonMap("error", "INTERNAL_ERROR", "message", "Erro interno do servidor"));
 35	            });
 36	
 37	        app.start(serverPort);
 38	        logger.info("Servidor iniciado na porta {}", serverPort);
 39	    }
 40	
 41	    public static java.util.Map<String, Object> jsonMap(Object... pairs) {
 42	        var map = new java.util.LinkedHashMap<String, Object>();
 43	        for (int i = 0; i < pairs.length; i += 2) {
 44	            map.put((String) pairs[i], pairs[i + 1]);
 45	        }
 46	        return map;
 47	    }
 48	}
 49	package com.pousadamareal.db;
 50	
 51	import org.slf4j.Logger;
 52	import org.slf4j.LoggerFactory;
 53	
 54	import java.sql.*;
 55	
 56	public class Database {
 57	    private static final Logger logger = LoggerFactory.getLogger(Database.class);
 58	    private static final String DB_URL = System.getenv("DB_URL");
 59	    private static final String DB_USER = System.getenv("DB_USER");
 60	    private static final String DB_PASSWORD = System.getenv("DB_PASSWORD");
 61	
 62	    public static void initialize() {
 63	        try (Connection conn = getConnection()) {
 64	            createTables(conn);
 65	            insertInitialData(conn);
 66	        } catch (SQLException e) {
 67	            logger.error("Erro ao inicializar banco de dados", e);
 68	            throw new RuntimeException(e);
 69	        }
 70	    }
 71	
 72	    public static Connection getConnection() throws SQLException {
 73	        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
 74	    }
 75	
 76	    private static void createTables(Connection conn) throws SQLException {
 77	        Statement stmt = conn.createStatement();
 78	
 79	        stmt.execute("""
 80	            CREATE TABLE IF NOT EXISTS rooms (
 81	                number INTEGER PRIMARY KEY,
 82	                type VARCHAR(20) NOT NULL,
 83	                capacity INTEGER NOT NULL,
 84	                nightly_rate NUMERIC(10, 2) NOT NULL
 85	            )
 86	        """);
 87	
 88	        stmt.execute("""
 89	            CREATE TABLE IF NOT EXISTS reservations (
 90	                id BIGSERIAL PRIMARY KEY,
 91	                room_number INTEGER NOT NULL REFERENCES rooms(number),
 92	                guest_name VARCHAR(255) NOT NULL,
 93	                guest_email VARCHAR(255) NOT NULL,
 94	                guest_cpf VARCHAR(11),
 95	                company_cnpj VARCHAR(14),
 96	                company_name VARCHAR(255),
 97	                guest_passport VARCHAR(20),
 98	                guest_country VARCHAR(2),
 99	                check_in DATE NOT NULL,
100	                check_out DATE NOT NULL,
101	                guests INTEGER NOT NULL,
102	                rate_plan VARCHAR(20) NOT NULL,
103	                nights INTEGER NOT NULL,
104	                subtotal NUMERIC(10, 2) NOT NULL,
105	                discount NUMERIC(10, 2) NOT NULL,
106	                total NUMERIC(10, 2) NOT NULL,
107	                status VARCHAR(20) NOT NULL,
108	                amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
109	                refund NUMERIC(10, 2)
110	            )
111	        """);
112	
113	        stmt.execute("""
114	            CREATE TABLE IF NOT EXISTS messages (
115	                id BIGSERIAL PRIMARY KEY,
116	                channel VARCHAR(20) NOT NULL,
117	                recipient VARCHAR(255) NOT NULL,
118	                subject VARCHAR(255),
119	                body TEXT NOT NULL
120	            )
121	        """);
122	
123	        stmt.close();
124	    }
125	
126	    private static void insertInitialData(Connection conn) throws SQLException {
127	        Statement stmt = conn.createStatement();
128	
129	        String checkRooms = "SELECT COUNT(*) FROM rooms";
130	        ResultSet rs = stmt.executeQuery(checkRooms);
131	        rs.next();
132	        if (rs.getInt(1) == 0) {
133	            stmt.execute("INSERT INTO rooms VALUES (101, 'STANDARD', 2, 249.90)");
134	            stmt.execute("INSERT INTO rooms VALUES (102, 'STANDARD', 2, 249.90)");
135	            stmt.execute("INSERT INTO rooms VALUES (201, 'DELUXE', 3, 389.90)");
136	            stmt.execute("INSERT INTO rooms VALUES (202, 'DELUXE', 3, 389.90)");
137	            stmt.execute("INSERT INTO rooms VALUES (301, 'SUITE', 4, 579.90)");
138	        }
139	
140	        stmt.close();
141	    }
142	}
143	package com.pousadamareal.handler;
144	
145	import com.google.gson.JsonObject;
146	import com.google.gson.JsonParser;
147	import com.pousadamareal.model.*;
148	import com.pousadamareal.repository.RoomRepository;
149	import com.pousadamareal.service.DocumentGenerator;
150	import com.pousadamareal.service.ReservationService;
151	import com.pousadamareal.util.JsonUtils;
152	import io.javalin.http.Context;
153	import io.javalin.http.HttpStatus;
154	
155	import java.math.BigDecimal;
156	import java.sql.SQLException;
157	import java.time.LocalDate;
158	import java.time.format.DateTimeParseException;
159	import java.util.Optional;
160	
161	public class ReservationHandler {
162	
163	    public static void create(Context ctx) {
164	        try {
165	            String body = ctx.body();
166	            JsonObject json = JsonParser.parseString(body).getAsJsonObject();
167	
168	            if (!json.has("roomNumber") || !json.has("guestName") || !json.has("guestEmail") ||
169	                !json.has("checkIn") || !json.has("checkOut") || !json.has("guests") || !json.has("ratePlan")) {
170	                ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "Campos obrigatórios faltam"));
171	                return;
172	            }
173	
174	            int roomNumber;
175	            String guestName;
176	            String guestEmail;
177	            String guestCpf = null;
178	            String companyCnpj = null;
179	            String companyName = null;
180	            String guestPassport = null;
181	            String guestCountry = null;
182	            LocalDate checkIn;
183	            LocalDate checkOut;
184	            int guests;
185	            RatePlan ratePlan;
186	
187	            try {
188	                roomNumber = json.get("roomNumber").getAsInt();
189	                guestName = json.get("guestName").getAsString();
190	                guestEmail = json.get("guestEmail").getAsString();
191	                checkIn = LocalDate.parse(json.get("checkIn").getAsString());
192	                checkOut = LocalDate.parse(json.get("checkOut").getAsString());
193	                guests = json.get("guests").getAsInt();
194	                ratePlan = RatePlan.valueOf(json.get("ratePlan").getAsString());
195	            } catch (NumberFormatException | DateTimeParseException e) {
196	                ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "Formato inválido"));
197	                return;
198	            }
199	
200	            int identificationCount = 0;
201	            if (json.has("guestCpf")) {
202	                guestCpf = json.get("guestCpf").getAsString();
203	                identificationCount++;
204	            }
205	            if (json.has("companyCnpj")) {
206	                companyCnpj = json.get("companyCnpj").getAsString();
207	                identificationCount++;
208	            }
209	            if (json.has("guestPassport")) {
210	                guestPassport = json.get("guestPassport").getAsString();
211	                identificationCount++;
212	            }
213	
214	            if (identificationCount != 1) {
215	                ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "Deve informar exatamente um tipo de identificação"));
216	                return;
217	            }
218	
219	            if (json.has("companyCnpj") && !json.has("companyName")) {
220	                ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "companyName é obrigatório com companyCnpj"));
221	                return;
222	            }
223	
224	            if (json.has("guestPassport") && !json.has("guestCountry")) {
225	                ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "guestCountry é obrigatório com guestPassport"));
226	                return;
227	            }
228	
229	            if (json.has("companyName")) {
230	                companyName = json.get("companyName").getAsString();
231	            }
232	            if (json.has("guestCountry")) {
233	                guestCountry = json.get("guestCountry").getAsString();
234	            }
235	
236	            try {
237	                Reservation reservation = ReservationService.create(
238	                    roomNumber, guestName, guestEmail,
239	                    guestCpf, companyCnpj, companyName,
240	                    guestPassport, guestCountry,
241	                    checkIn, checkOut, guests, ratePlan
242	                );
243	                ctx.status(HttpStatus.CREATED).json(toJson(reservation));
244	            } catch (IllegalArgumentException e) {
245	                handleError(ctx, e.getMessage());
246	            }
247	        } catch (SQLException e) {
248	            ctx.status(500).json(JsonUtils.map("error", "INTERNAL_ERROR", "message", e.getMessage()));
249	        } catch (Exception e) {
250	            ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "Erro ao processar requisição"));
251	        }
252	    }
253	
254	    public static void get(Context ctx) {
255	        try {
256	            long id = Long.parseLong(ctx.pathParam("id"));
257	            Reservation reservation = ReservationService.getById(id);
258	            ctx.json(toJson(reservation));
259	        } catch (NumberFormatException e) {
260	            ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "ID inválido"));
261	        } catch (IllegalArgumentException e) {
262	            handleError(ctx, e.getMessage());
263	        } catch (SQLException e) {
264	            ctx.status(500).json(JsonUtils.map("error", "INTERNAL_ERROR", "message", e.getMessage()));
265	        }
266	    }
267	
268	    public static void confirm(Context ctx) {
269	        try {
270	            long id = Long.parseLong(ctx.pathParam("id"));
271	            String body = ctx.body();
272	            JsonObject json = JsonParser.parseString(body).getAsJsonObject();
273	
274	            if (!json.has("amountPaid")) {
275	                ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "amountPaid é obrigatório"));
276	                return;
277	            }
278	
279	            BigDecimal amountPaid = json.get("amountPaid").getAsBigDecimal();
280	            Reservation reservation = ReservationService.confirm(id, amountPaid);
281	            ctx.json(toJson(reservation));
282	        } catch (NumberFormatException e) {
283	            ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "ID ou valor inválido"));
284	        } catch (IllegalArgumentException e) {
285	            handleError(ctx, e.getMessage());
286	        } catch (SQLException e) {
287	            ctx.status(500).json(JsonUtils.map("error", "INTERNAL_ERROR", "message", e.getMessage()));
288	        } catch (Exception e) {
289	            ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "Erro ao processar requisição"));
290	        }
291	    }
292	
293	    public static void cancel(Context ctx) {
294	        try {
295	            long id = Long.parseLong(ctx.pathParam("id"));
296	            Reservation reservation = ReservationService.cancel(id);
297	            ctx.json(toJson(reservation));
298	        } catch (NumberFormatException e) {
299	            ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "ID inválido"));
300	        } catch (IllegalArgumentException e) {
301	            handleError(ctx, e.getMessage());
302	        } catch (SQLException e) {
303	            ctx.status(500).json(JsonUtils.map("error", "INTERNAL_ERROR", "message", e.getMessage()));
304	        }
305	    }
306	
307	    public static void checkIn(Context ctx) {
308	        try {
309	            long id = Long.parseLong(ctx.pathParam("id"));
310	            Reservation reservation = ReservationService.checkIn(id);
311	            ctx.json(toJson(reservation));
312	        } catch (NumberFormatException e) {
313	            ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "ID inválido"));
314	        } catch (IllegalArgumentException e) {
315	            handleError(ctx, e.getMessage());
316	        } catch (SQLException e) {
317	            ctx.status(500).json(JsonUtils.map("error", "INTERNAL_ERROR", "message", e.getMessage()));
318	        }
319	    }
320	
321	    public static void checkOut(Context ctx) {
322	        try {
323	            long id = Long.parseLong(ctx.pathParam("id"));
324	            Reservation reservation = ReservationService.checkOut(id);
325	
326	            Optional<Room> room = RoomRepository.findByNumber(reservation.roomNumber());
327	            Document document = DocumentGenerator.generate(reservation, room.get());
328	
329	            ctx.json(documentToJson(document));
330	        } catch (NumberFormatException e) {
331	            ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "ID inválido"));
332	        } catch (IllegalArgumentException e) {
333	            handleError(ctx, e.getMessage());
334	        } catch (SQLException e) {
335	            ctx.status(500).json(JsonUtils.map("error", "INTERNAL_ERROR", "message", e.getMessage()));
336	        }
337	    }
338	
339	    public static void getDocument(Context ctx) {
340	        try {
341	            long id = Long.parseLong(ctx.pathParam("id"));
342	            Reservation reservation = ReservationService.getById(id);
343	
344	            if (reservation.status() == ReservationStatus.PENDING || reservation.status() == ReservationStatus.CANCELLED) {
345	                ctx.status(409).json(JsonUtils.map("error", "OPERATION_NOT_ALLOWED", "message", "Documento não disponível"));
346	                return;
347	            }
348	
349	            Optional<Room> room = RoomRepository.findByNumber(reservation.roomNumber());
350	            Document document = DocumentGenerator.generate(reservation, room.get());
351	
352	            ctx.json(documentToJson(document));
353	        } catch (NumberFormatException e) {
354	            ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "ID inválido"));
355	        } catch (IllegalArgumentException e) {
356	            handleError(ctx, e.getMessage());
357	        } catch (SQLException e) {
358	            ctx.status(500).json(JsonUtils.map("error", "INTERNAL_ERROR", "message", e.getMessage()));
359	        }
360	    }
361	
362	    private static void handleError(Context ctx, String error) {
363	        switch (error) {
364	            case "ROOM_NOT_FOUND":
365	                ctx.status(404).json(JsonUtils.map("error", "ROOM_NOT_FOUND", "message", "Quarto não encontrado"));
366	                break;
367	            case "RESERVATION_NOT_FOUND":
368	                ctx.status(404).json(JsonUtils.map("error", "RESERVATION_NOT_FOUND", "message", "Reserva não encontrada"));
369	                break;
370	            case "ROOM_UNAVAILABLE":
371	                ctx.status(409).json(JsonUtils.map("error", "ROOM_UNAVAILABLE", "message", "Quarto não está disponível"));
372	                break;
373	            case "CAPACITY_EXCEEDED":
374	                ctx.status(422).json(JsonUtils.map("error", "CAPACITY_EXCEEDED", "message", "Excedeu a capacidade do quarto"));
375	                break;
376	            case "OPERATION_NOT_ALLOWED":
377	                ctx.status(409).json(JsonUtils.map("error", "OPERATION_NOT_ALLOWED", "message", "Operação não permitida"));
378	                break;
379	            case "INVALID_REQUEST":
380	                ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", "Requisição inválida"));
381	                break;
382	            default:
383	                ctx.status(400).json(JsonUtils.map("error", "INVALID_REQUEST", "message", error));
384	        }
385	    }
386	
387	    private static java.util.Map<String, Object> toJson(Reservation reservation) {
388	        return JsonUtils.map(
389	            "id", reservation.id(),
390	            "roomNumber", reservation.roomNumber(),
391	            "guestName", reservation.guestName(),
392	            "guestEmail", reservation.guestEmail(),
393	            "guestCpf", reservation.guestCpf(),
394	            "companyCnpj", reservation.companyCnpj(),
395	            "companyName", reservation.companyName(),
396	            "guestPassport", reservation.guestPassport(),
397	            "guestCountry", reservation.guestCountry(),
398	            "checkIn", reservation.checkIn().toString(),
399	            "checkOut", reservation.checkOut().toString(),
400	            "guests", reservation.guests(),
401	            "ratePlan", reservation.ratePlan().name(),
402	            "nights", reservation.nights(),
403	            "subtotal", reservation.subtotal(),
404	            "discount", reservation.discount(),
405	            "total", reservation.total(),
406	            "status", reservation.status().name(),
407	            "amountPaid", reservation.amountPaid(),
408	            "refund", reservation.refund()
409	        );
410	    }
411	
412	    private static java.util.Map<String, Object> documentToJson(Document document) {
413	        return JsonUtils.map(
414	            "title", document.title(),
415	            "reservationId", document.reservationId(),
416	            "guestName", document.guestName(),
417	            "guestCpf", document.guestCpf(),
418	            "companyCnpj", document.companyCnpj(),
419	            "companyName", document.companyName(),
420	            "guestPassport", document.guestPassport(),
421	            "guestCountry", document.guestCountry(),
422	            "roomNumber", document.roomNumber(),
423	            "roomType", document.roomType(),
424	            "checkIn", document.checkIn(),
425	            "checkOut", document.checkOut(),
426	            "nights", document.nights(),
427	            "subtotal", document.subtotal(),
428	            "discount", document.discount(),
429	            "total", document.total(),
430	            "text", document.text()
431	        );
432	    }
433	}

