 11	public class DocumentGenerator {
 12	    private static final DateTimeFormatter DATE_FORMAT_PT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 13	    private static final DateTimeFormatter DATE_FORMAT_EN = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 14	
 15	    public static Document generate(Reservation reservation, Room room) {
 16	        String text;
 17	        String title;
 18	        String checkInFormatted;
 19	        String checkOutFormatted;
 20	
 21	        if (reservation.guestCpf() != null) {
 22	            text = generateComprovante(reservation, room);
 23	            title = "Comprovante de reserva";
 24	            checkInFormatted = reservation.checkIn().format(DATE_FORMAT_PT);
 25	            checkOutFormatted = reservation.checkOut().format(DATE_FORMAT_PT);
 26	        } else if (reservation.companyCnpj() != null) {
 27	            text = generateFatura(reservation, room);
 28	            title = "Fatura de hospedagem";
 29	            checkInFormatted = reservation.checkIn().format(DATE_FORMAT_PT);
 30	            checkOutFormatted = reservation.checkOut().format(DATE_FORMAT_PT);
 31	        } else {
 32	            text = generateBookingReceipt(reservation, room);
 33	            title = "Booking receipt";
 34	            checkInFormatted = reservation.checkIn().format(DATE_FORMAT_EN);
 35	            checkOutFormatted = reservation.checkOut().format(DATE_FORMAT_EN);
 36	        }
 37	
 38	        return new Document(
 39	            title,
 40	            reservation.id(),
 41	            reservation.guestName(),
 42	            reservation.guestCpf(),
 43	            reservation.companyCnpj(),
 44	            reservation.companyName(),
 45	            reservation.guestPassport(),
 46	            reservation.guestCountry(),
 47	            reservation.roomNumber(),
 48	            room.type().name(),
 49	            checkInFormatted,
 50	            checkOutFormatted,
 51	            reservation.nights(),
 52	            reservation.subtotal(),
 53	            reservation.discount(),
 54	            reservation.total(),
 55	            text
 56	        );
 57	    }
 58	
 59	    private static String generateComprovante(Reservation reservation, Room room) {
 60	        String nights = reservation.nights() == 1 ? "1 diária" : reservation.nights() + " diárias";
 61	        String cpfFormatted = formatCpf(reservation.guestCpf());
 62	
 63	        StringBuilder sb = new StringBuilder();
 64	        sb.append("Comprovante de reserva nº ").append(reservation.id()).append("\n");
 65	        sb.append("Hóspede: ").append(reservation.guestName()).append(" (CPF ").append(cpfFormatted).append(")\n");
 66	        sb.append("Quarto: ").append(reservation.roomNumber()).append(" (").append(room.type().name()).append(")\n");
 67	        sb.append("Entrada: ").append(reservation.checkIn().format(DATE_FORMAT_PT));
 68	        sb.append(" | Saída: ").append(reservation.checkOut().format(DATE_FORMAT_PT));
 69	        sb.append(" | ").append(nights).append("\n");
 70	        sb.append("Diárias: ").append(formatMoney(reservation.subtotal())).append("\n");
 71	
 72	        if (reservation.discount().compareTo(BigDecimal.ZERO) > 0) {
 73	            sb.append("Desconto: ").append(formatMoney(reservation.discount())).append("\n");
 74	        }
 75	
 76	        sb.append("Total: ").append(formatMoney(reservation.total()));
 77	
 78	        return sb.toString();
 79	    }
 80	
 81	    private static String generateFatura(Reservation reservation, Room room) {
 82	        String nights = reservation.nights() == 1 ? "1 diária" : reservation.nights() + " diárias";
 83	        String cnpjFormatted = formatCnpj(reservation.companyCnpj());
 84	        BigDecimal iss = PricingUtils.calculateIss(reservation.total());
 85	
 86	        StringBuilder sb = new StringBuilder();
 87	        sb.append("Fatura de hospedagem nº ").append(reservation.id()).append("\n");
 88	        sb.append("Empresa: ").append(reservation.companyName()).append(" (CNPJ ").append(cnpjFormatted).append(")\n");
 89	        sb.append("Hóspede: ").append(reservation.guestName()).append("\n");
 90	        sb.append("Quarto: ").append(reservation.roomNumber()).append(" (").append(room.type().name()).append(")\n");
 91	        sb.append("Entrada: ").append(reservation.checkIn().format(DATE_FORMAT_PT));
 92	        sb.append(" | Saída: ").append(reservation.checkOut().format(DATE_FORMAT_PT));
 93	        sb.append(" | ").append(nights).append("\n");
 94	        sb.append("Diárias: ").append(formatMoney(reservation.subtotal())).append("\n");
 95	
 96	        if (reservation.discount().compareTo(BigDecimal.ZERO) > 0) {
 97	            sb.append("Desconto: ").append(formatMoney(reservation.discount())).append("\n");
 98	        }
 99	
100	        sb.append("Total: ").append(formatMoney(reservation.total())).append("\n");
101	        sb.append("ISS retido (5%): ").append(formatMoney(iss));
102	
103	        return sb.toString();
104	    }
105	
106	    private static String generateBookingReceipt(Reservation reservation, Room room) {
107	        String nights = reservation.nights() == 1 ? "1 night" : reservation.nights() + " nights";
108	        String passportCountry = reservation.guestPassport() + ", " + reservation.guestCountry();
109	
110	        StringBuilder sb = new StringBuilder();
111	        sb.append("Booking receipt no. ").append(reservation.id()).append("\n");
112	        sb.append("Guest: ").append(reservation.guestName()).append(" (passport ").append(passportCountry).append(")\n");
113	        sb.append("Room: ").append(reservation.roomNumber()).append(" (").append(room.type().name()).append(")\n");
114	        sb.append("Check-in: ").append(reservation.checkIn().format(DATE_FORMAT_EN));
115	        sb.append(" | Check-out: ").append(reservation.checkOut().format(DATE_FORMAT_EN));
116	        sb.append(" | ").append(nights).append("\n");
117	        sb.append("Nights: ").append(formatMoneyEn(reservation.subtotal())).append("\n");
118	
119	        if (reservation.discount().compareTo(BigDecimal.ZERO) > 0) {
120	            sb.append("Discount: ").append(formatMoneyEn(reservation.discount())).append("\n");
121	        }
122	
123	        sb.append("Total: ").append(formatMoneyEn(reservation.total()));
124	
125	        return sb.toString();
126	    }
127	
128	    private static String formatMoney(BigDecimal value) {
129	        return "R$ " + String.format("%,.2f", value).replace(",", "X").replace(".", ",").replace("X", ".");
130	    }
131	
132	    private static String formatMoneyEn(BigDecimal value) {
133	        return "BRL " + String.format("%,.2f", value);
134	    }
135	
136	    private static String formatCpf(String cpf) {
137	        if (cpf == null || cpf.length() != 11) return cpf;
138	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
139	    }
140	
141	    private static String formatCnpj(String cnpj) {
142	        if (cnpj == null || cnpj.length() != 14) return cnpj;
143	        return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "." + cnpj.substring(5, 8) + "/" +
144	               cnpj.substring(8, 12) + "-" + cnpj.substring(12);
145	    }
146	}
147	package com.pousadamareal.service;
148	
149	import java.math.BigDecimal;
150	import java.math.RoundingMode;
151	import java.time.LocalDate;
152	
153	public class PricingUtils {
154	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
155	    private static final BigDecimal DISCOUNT_RATE = BigDecimal.valueOf(0.15);
156	
157	    public static boolean isHighSeason(LocalDate date) {
158	        int month = date.getMonthValue();
159	        int day = date.getDayOfMonth();
160	
161	        if (month == 7) {
162	            return true;
163	        }
164	
165	        if (month == 12) {
166	            return day >= 15;
167	        }
168	
169	        if (month >= 1 && month <= 2) {
170	            return true;
171	        }
172	
173	        return false;
174	    }
175	
176	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
177	        if (isHighSeason(date)) {
178	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
179	        }
180	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
181	    }
182	
183	    public static BigDecimal calculateSubtotal(BigDecimal nightlyRate, int nights) {
184	        return nightlyRate.multiply(BigDecimal.valueOf(nights)).setScale(2, RoundingMode.HALF_EVEN);
185	    }
186	
187	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
188	        if ("NON_REFUNDABLE".equals(ratePlan)) {
189	            return subtotal.multiply(DISCOUNT_RATE).setScale(2, RoundingMode.HALF_EVEN);
190	        }
191	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
192	    }
193	
194	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
195	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
196	    }
197	
198	    public static BigDecimal calculateIss(BigDecimal total) {
199	        return total.multiply(BigDecimal.valueOf(0.05)).setScale(2, RoundingMode.HALF_EVEN);
200	    }
201	}
