379	    public static Reservation confirm(long id, BigDecimal amountPaid) throws SQLException {
380	        Reservation reservation = getById(id);
381	
382	        if (reservation.status() != ReservationStatus.PENDING) {
383	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
384	        }
385	
386	        Reservation updated = reservation
387	            .withStatus(ReservationStatus.CONFIRMED)
388	            .withAmountPaid(amountPaid);
389	
390	        ReservationRepository.update(updated);
391	
392	        Optional<Room> room = RoomRepository.findByNumber(reservation.roomNumber());
393	        Document document = DocumentGenerator.generate(updated, room.get());
394	
395	        sendConfirmationEmail(updated, document);
396	
397	        return updated;
398	    }
399	
400	    public static Reservation cancel(long id) throws SQLException {
401	        Reservation reservation = getById(id);
402	
403	        if (reservation.status() == ReservationStatus.CHECKED_IN ||
404	            reservation.status() == ReservationStatus.CHECKED_OUT ||
405	            reservation.status() == ReservationStatus.CANCELLED) {
406	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
407	        }
408	
409	        BigDecimal refund = BigDecimal.ZERO;
410	        if (reservation.status() == ReservationStatus.CONFIRMED) {
411	            if (reservation.ratePlan() == RatePlan.STANDARD) {
412	                refund = reservation.amountPaid();
413	            }
414	        }
415	
416	        Reservation updated = reservation
417	            .withStatus(ReservationStatus.CANCELLED)
418	            .withRefund(refund);
419	
420	        ReservationRepository.update(updated);
421	        return updated;
422	    }
423	
424	    public static Reservation checkIn(long id) throws SQLException {
425	        Reservation reservation = getById(id);
426	
427	        if (reservation.status() != ReservationStatus.CONFIRMED) {
428	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
429	        }
430	
431	        Reservation updated = reservation.withStatus(ReservationStatus.CHECKED_IN);
432	        ReservationRepository.update(updated);
433	        return updated;
434	    }
435	
436	    public static Reservation checkOut(long id) throws SQLException {
437	        Reservation reservation = getById(id);
438	
439	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
440	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
441	        }
442	
443	        Reservation updated = reservation.withStatus(ReservationStatus.CHECKED_OUT);
444	        ReservationRepository.update(updated);
445	        return updated;
446	    }
447	
448	    private static void sendConfirmationEmail(Reservation reservation, Document document) throws SQLException {
449	        String emailBody = buildConfirmationEmailBody(reservation.guestName(), document.text());
450	
451	        Message message = new Message(
452	            0,
453	            "EMAIL",
454	            reservation.guestEmail(),
455	            "Reserva confirmada - Pousada Maré Alta",
456	            emailBody
457	        );
458	
459	        MessageRepository.save(message);
460	    }
461	
462	    private static String buildConfirmationEmailBody(String guestName, String documentText) {
463	        return "Olá, " + guestName + "!\n\n" +
464	               "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
465	               documentText + "\n\n" +
466	               "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
467	               "Até breve!";
468	    }
469	}

