194	                 "FROM reservations WHERE (status = 'CONFIRMED' OR status = 'CHECKED_IN' OR status = 'CHECKED_OUT' OR status = 'CANCELLED') " +
195	                 "AND check_in >= ? AND check_in <= ? " +
