169	                 "FROM reservations WHERE (status = 'CONFIRMED' OR status = 'CHECKED_IN' OR status = 'CHECKED_OUT') " +
170	                 "AND check_in <= ? AND check_out > ? " +
171	                 "ORDER BY room_number")) {
172	
173	            stmt.setDate(1, java.sql.Date.valueOf(date));
