185	    public static List<Reservation> findByMonthForRevenue(int year, int month) throws SQLException {
186	        List<Reservation> reservations = new ArrayList<>();
187	        LocalDate startOfMonth = LocalDate.of(year, month, 1);
188	        LocalDate endOfMonth = startOfMonth.plusMonths(1).minusDays(1);
189	
190	        try (Connection conn = Database.getConnection();
191	             PreparedStatement stmt = conn.prepareStatement(
192	                 "SELECT id, room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name, " +
193	                 "guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund " +
194	                 "FROM reservations WHERE (status = 'CONFIRMED' OR status = 'CHECKED_IN' OR status = 'CHECKED_OUT' OR status = 'CANCELLED') " +
195	                 "AND check_in >= ? AND check_in <= ? " +
196	                 "AND (amount_paid > 0 OR (status = 'CANCELLED' AND refund IS NOT NULL)) " +
197	                 "ORDER BY check_in, id")) {
198	
199	            stmt.setDate(1, java.sql.Date.valueOf(startOfMonth));
200	            stmt.setDate(2, java.sql.Date.valueOf(endOfMonth));
201	
202	            try (ResultSet rs = stmt.executeQuery()) {
203	                while (rs.next()) {
204	                    reservations.add(mapReservation(rs));
205	                }
206	            }
207	        }
208	        return reservations;
209	    }
